            $display("FAIL: Reset did not set q to 0. Got %d", q);
        end

        // Release reset
        reset = 0;

        // Test 2: Normal counting sequence 0 through 9 and rollover back to 0
        for (i = 0; i <= 11; i = i + 1) begin
            @(posedge clk);
            #1; // Allow output to update

            // Expected value should be (i % 10) because we started after reset at 0
            if (q !== (i % 10)) begin
                errors = errors + 1;
                $display("FAIL: At step %0d, expected %0d, got %0d", i, (i % 10), q);
            end
        end

        // Test 3: Asynchronous/unexpected state recovery test
        // Let's check boundary conditions if state somehow gets jammed above 9 (illegal states 10-15).
        // Since we cannot force DUT internal variables directly due to strict rules, 
        // we test if reset forcefully pulls illegal-state counters back to 0 immediately.
        @(posedge clk);
        reset = 1;
        @(posedge clk);
        #1;
        if (q !== 4'd0) begin
            errors = errors + 1;
            $display("FAIL: Reset from running state failed to clear q to 0. Got %d", q);
        end
        reset = 0;

        // Final Result Display
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
